WITH not_flagged AS (SELECT s.* FROM products s WHERE EXISTS (SELECT 1 FROM order_items x WHERE x.product_id = s.id AND x.product_id = 23)) SELECT CASE WHEN cost >= 550 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, COUNT(*) FILTER (WHERE category = 'Electronics') AS electronics_rows, COUNT(DISTINCT category) AS distinct_categories, SUM(cost) FILTER (WHERE category = 'Fashion') AS fashion_total_cost, BIT_OR(stock_qty) AS stock_qty_bit_or, APPROX_PERCENTILE(price, ARRAY(0.25, 0.5, 0.75)) AS price_quartiles, COUNT(*) AS cnt FROM not_flagged GROUP BY CASE WHEN cost >= 550 THEN 'HIGH' ELSE 'LOW' END ORDER BY cost_tier DESC NULLS LAST
